     1→/**
     2→ * VideoPlayerView — react-native-video wrapper for the status viewer.
     3→ *
     4→ * WHY react-native-video (not expo-video)
     5→ * ────────────────────────────────────────
     6→ * Diagnosis from test screens A / B / C on a real Android 11+ device:
     7→ *
     8→ *   Screen A — expo-video   + file:// (copy path) → fully frozen (0 s)
     9→ *   Screen B — expo-video   + content://          → freeze at ~1 s
    10→ *   Screen C — react-native-video + content://    → plays (stutters at 1 s
    11→ *                                                    buffer boundary)
    12→ *
    13→ * Conclusion: expo-video / Media3 is broken on this device.
    14→ * Fix: replace the player library while keeping the already-correct
    15→ *      copy-to-cache flow in ViewerItem (content:// → file://).
    16→ *
    17→ * RERENDER ISOLATION
    18→ * ──────────────────
    19→ * VideoPlayerView is React.memo-wrapped (outer shell).
    20→ * The <Video> element is further isolated inside StableVideo, a second
    21→ * React.memo layer that re-renders ONLY when fileUri or paused changes.
    22→ *
    23→ * PAUSE / RESUME
    24→ * ──────────────
    25→ * paused = !isActive || appState !== 'active'
    26→ * isActive changes are debounced 400 ms to absorb FlatList transient flickers.
    27→ * appState changes are applied immediately (background → paused instantly).
    28→ *
    29→ * LOGGING — 4 tags only:
    30→ *   [PAUSE-REASON]  — why paused changed (isActive / appState / finalPaused)
    31→ *   [VIDEO-PROP]    — paused prop value reaching <Video> (detects flip-flop)
    32→ *   [VIDEO] READY   — onReadyForDisplay fireCount (detects surface recreation)
    33→ *   [VIDEO-STATE]   — onPlaybackStateChanged isPlaying / isSeeking
    34→ */
    35→import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
    36→import { StyleSheet, AppState, AppStateStatus } from 'react-native';
    37→import Video, {
    38→  OnVideoErrorData,
    39→  OnPlaybackStateChangedData,
    40→} from 'react-native-video';
    41→
    42→interface VideoPlayerViewProps {
    43→  fileUri: string;
    44→  isActive: boolean;
    45→  onPlaying: () => void;
    46→  onError: (message: string) => void;
    47→}
    48→
    49→interface StableVideoProps {
    50→  fileUri: string;
    51→  paused: boolean;
    52→  onReadyForDisplay: () => void;
    53→  onEnd: () => void;
    54→  onError: (d: OnVideoErrorData) => void;
    55→  onPlaybackStateChanged: (d: OnPlaybackStateChangedData) => void;
    56→}
    57→
    58→// ─── Module-level constants — never recreated, always same reference ──────────
    59→const BUFFER_CONFIG = {
    60→  minBufferMs: 15000,
    61→  maxBufferMs: 50000,
    62→  bufferForPlaybackMs: 2500,
    63→  bufferForPlaybackAfterRebufferMs: 5000,
    64→} as const;
    65→
    66→const STABLE_STYLE = StyleSheet.absoluteFill;
    67→
    68→// ─── StableVideo ──────────────────────────────────────────────────────────────
    69→// Inner isolation layer. Re-renders ONLY when fileUri or paused changes.
    70→// All callbacks are created once in the outer VideoPlayerView and never change.
    71→const StableVideo = React.memo(function StableVideo(p: StableVideoProps) {
    72→  const source = useMemo(() => ({ uri: p.fileUri }), [p.fileUri]);
    73→  const videoRef = useRef<{ seek: (time: number) => void } | null>(null);
    74→
    75→  // Manual loop: seek(0) on end rather than repeat={true}.
    76→  // repeat={true} uses ExoPlayer's built-in looping which fires
    77→  // END → SEEK(0) → BUFFERING → PLAYING at every boundary, causing
    78→  // the surface to detach/reattach and onReadyForDisplay to repeat.
    79→  const handleEndInternal = useCallback(() => {
    80→    videoRef.current?.seek(0);
    81→    p.onEnd();
    82→  // p.onEnd is useCallback([]) in VideoPlayerView — always the same ref
    83→  // eslint-disable-next-line react-hooks/exhaustive-deps
    84→  }, []);
    85→
    86→  return (
    87→    <Video
    88→      ref={videoRef as any}
    89→      source={source}
    90→      style={STABLE_STYLE}
    91→      resizeMode="contain"
    92→      repeat={false}
    93→      paused={p.paused}
    94→      muted={false}
    95→      controls={false}
    96→      useTextureView={true}
    97→      bufferConfig={BUFFER_CONFIG}
    98→      progressUpdateInterval={500}
    99→      onReadyForDisplay={p.onReadyForDisplay}
   100→      onEnd={handleEndInternal}
   101→      onError={p.onError}
   102→      onPlaybackStateChanged={p.onPlaybackStateChanged}
   103→      ignoreSilentSwitch="ignore"
   104→      playInBackground={false}
   105→    />
   106→  );
   107→}, (prev, next) =>
   108→  prev.fileUri === next.fileUri &&
   109→  prev.paused === next.paused
   110→);
   111→
   112→// ─── Mounted instance counter (exported for debugging) ────────────────────────
   113→let _mountedCount = 0;
   114→export function getActiveMountedCount(): number { return _mountedCount; }
   115→
   116→// ─── VideoPlayerView ──────────────────────────────────────────────────────────
   117→export const VideoPlayerView = React.memo(function VideoPlayerView({
   118→  fileUri,
   119→  isActive,
   120→  onPlaying,
   121→  onError,
   122→}: VideoPlayerViewProps) {
   123→  const manuallyPaused = false; // no manual-pause UI in this app
   124→
   125→  // ── Track OS lifecycle ───────────────────────────────────────────────────
   126→  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState);
   127→  useEffect(() => {
   128→    const sub = AppState.addEventListener('change', (next: AppStateStatus) => {
   129→      setAppState(next);
   130→    });
   131→    return () => sub.remove();
   132→  }, []);
   133→
   134→  // ── Pause logic ──────────────────────────────────────────────────────────
   135→  // paused = slide not active OR app not in foreground.
   136→  // isActive changes are debounced 400 ms to absorb FlatList transient flips.
   137→  // appState changes (background) are applied immediately via the effect above.
   138→  const [paused, setPaused] = useState(!isActive || appState !== 'active');
   139→  const pauseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
   140→  const isActiveRef = useRef(isActive);
   141→  isActiveRef.current = isActive;
   142→
   143→  useEffect(() => {
   144→    if (pauseTimerRef.current) {
   145→      clearTimeout(pauseTimerRef.current);
   146→      pauseTimerRef.current = null;
   147→    }
   148→    if (isActive) {
   149→      setPaused(appState !== 'active');
   150→    } else {
   151→      pauseTimerRef.current = setTimeout(() => {
   152→        pauseTimerRef.current = null;
   153→        if (!isActiveRef.current) setPaused(true);
   154→      }, 400);
   155→    }
   156→  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps
   157→
   158→  // Apply appState changes immediately on top of the isActive-based paused.
   159→  useEffect(() => {
   160→    if (appState !== 'active') {
   161→      setPaused(true);
   162→    } else if (isActiveRef.current) {
   163→      setPaused(false);
   164→    }
   165→  }, [appState]);
   166→
   167→  useEffect(() => {
   168→    _mountedCount++;
   169→    return () => {
   170→      _mountedCount--;
   171→      if (pauseTimerRef.current) {
   172→        clearTimeout(pauseTimerRef.current);
   173→        pauseTimerRef.current = null;
   174→      }
   175→    };
   176→  }, []);
   177→
   178→  // ── [PAUSE-REASON] ───────────────────────────────────────────────────────
   179→  // Logs every time the pause decision changes. Key diagnostic:
   180→  //   If finalPaused flips true/false in sync with appState → AppState loop.
   181→  //   If finalPaused stays false while video freezes → below-RN issue.
   182→  useEffect(() => {
   183→    console.log(
   184→      `[PAUSE-REASON]\n     activeItem=${isActive}\n     appState=${appState}\n     manuallyPaused=${manuallyPaused}\n     finalPaused=${paused}`,
   185→    );
   186→  }, [paused, isActive, appState]); // eslint-disable-line react-hooks/exhaustive-deps
   187→
   188→  // ── [VIDEO-PROP] ─────────────────────────────────────────────────────────
   189→  // Logs every time the paused prop value reaching <Video> actually changes.
   190→  // If this shows paused=true / paused=false alternating → the pause loop
   191→  // is coming from JS. If it stays paused=false during the freeze → native.
   192→  const prevPausedRef = useRef<boolean | null>(null);
   193→  if (prevPausedRef.current !== paused) {
   194→    prevPausedRef.current = paused;
   195→    console.log('[VIDEO-PROP]', { paused, isActive, appState, manuallyPaused });
   196→  }
   197→
   198→  const hasCalledOnPlaying = useRef(false);
   199→  useEffect(() => {
   200→    hasCalledOnPlaying.current = false;
   201→  }, [isActive]);
   202→
   203→  // ── Stable callbacks ([] deps — never cause StableVideo re-render) ────────
   204→
   205→  const readyForDisplayCount = useRef(0);
   206→  const handleReadyForDisplay = useCallback(() => {
   207→    readyForDisplayCount.current += 1;
   208→    // [VIDEO] READY — fireCount > 1 means surface is being recreated.
   209→    console.log(`[VIDEO] READY ${Date.now()} fireCount=${readyForDisplayCount.current}`);
   210→    if (hasCalledOnPlaying.current) return;
   211→    hasCalledOnPlaying.current = true;
   212→    onPlaying();
   213→  // onPlaying is stable in ViewerItem
   214→  // eslint-disable-next-line react-hooks/exhaustive-deps
   215→  }, []);
   216→
   217→  const handleEnd = useCallback(() => {}, []);
   218→
   219→  const handleError = useCallback((e: OnVideoErrorData) => {
   220→    onError(e.error?.errorString ?? 'Playback error');
   221→  // eslint-disable-next-line react-hooks/exhaustive-deps
   222→  }, []);
   223→
   224→  const handlePlaybackStateChanged = useCallback((data: OnPlaybackStateChangedData) => {
   225→    // [VIDEO-STATE] — isPlaying=false during steady playback means ExoPlayer
   226→    // was externally paused (audio focus, AppState, surface detach).
   227→    console.log(
   228→      `[VIDEO-STATE]\n       isPlaying=${data.isPlaying}\n       isSeeking=${(data as any).isSeeking ?? 'n/a'}`,
   229→    );
   230→  }, []);
   231→
   232→  return (
   233→    <StableVideo
   234→      fileUri={fileUri}
   235→      paused={paused}
   236→      onReadyForDisplay={handleReadyForDisplay}
   237→      onEnd={handleEnd}
   238→      onError={handleError}
   239→      onPlaybackStateChanged={handlePlaybackStateChanged}
   240→    />
   241→  );
   242→});
