     1→// ─────────────────────────────────────────────────────────────────────────────
     2→// Thumbnail cache — Android 11+ scroll-lag killer.
     3→//
     4→// THE PROBLEM
     5→// Every cell in the home grid that points at a content:// URI from Storage
     6→// Access Framework forces Glide (inside expo-image) to round-trip the URI
     7→// through ContentResolver, then for videos to spin up MediaMetadataRetriever
     8→// to extract a frame. That produces 200-800 ms of CPU per cell on Android
     9→// 11+, which destroys scroll smoothness.
    10→//
    11→// THE FIX
    12→// Generate the thumbnails ONCE in a low-priority background queue and write
    13→// them to internal cache as plain file:// JPGs. The grid then renders pure
    14→// local files at near-zero CPU — the hot scroll path never touches SAF or
    15→// the video decoder again.
    16→//
    17→// SHAPE
    18→// - In-memory map (id -> file:// path) hydrated from AsyncStorage on boot
    19→//   so cold launch already has thumbs ready before the grid mounts.
    20→// - Tiny per-id pub/sub so a newly generated thumb only re-renders the ONE
    21→//   card that needs it — no cascade through the whole grid.
    22→// - Serialized queue with an idle gap between items so background work
    23→//   never competes with the user's scroll.
    24→// - For images we don't write a separate file; we just warm expo-image's
    25→//   own disk cache via Image.prefetch — the next render is instant.
    26→// - Atomic destination: we write to a .tmp file then rename, so a crash
    27→//   mid-write never leaves a half-decoded JPG on disk.
    28→// ─────────────────────────────────────────────────────────────────────────────
    29→
    30→import { Platform } from 'react-native';
    31→import * as FileSystem from 'expo-file-system/legacy';
    32→import * as VideoThumbnails from 'expo-video-thumbnails';
    33→import { Image as ExpoImage } from 'expo-image';
    34→import AsyncStorage from '@react-native-async-storage/async-storage';
    35→import * as SafReaderModule from '@/modules/saf-reader';
    36→
    37→export type ThumbItemType = 'image' | 'video';
    38→
    39→export interface ThumbItem {
    40→  id: string;
    41→  uri: string;
    42→  type: ThumbItemType;
    43→}
    44→
    45→const STORAGE_KEY = '@statusvault_thumb_cache_v1';
    46→// FileSystem.cacheDirectory is wiped by the OS under storage pressure — the
    47→// queue will simply regenerate on the next scan, so this is the right place.
    48→const CACHE_DIR_NAME = 'status-thumbs/';
    49→
    50→// Module state — single instance per JS context (no React rerenders).
    51→let cacheDir: string | null = null;
    52→let memMap: Record<string, string> = {};
    53→const imagesPrefetched = new Set<string>();
    54→const subs = new Map<string, Set<(p: string | null) => void>>();
    55→let queue: ThumbItem[] = [];
    56→let processing = false;
    57→let cancelToken = 0;
    58→let initPromise: Promise<void> | null = null;
    59→let persistTimer: ReturnType<typeof setTimeout> | null = null;
    60→
    61→function safeFilename(id: string): string {
    62→  return id.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120);
    63→}
    64→
    65→function notify(id: string, path: string | null) {
    66→  const set = subs.get(id);
    67→  if (!set || set.size === 0) return;
    68→  set.forEach((cb) => {
    69→    try {
    70→      cb(path);
    71→    } catch {
    72→      // subscriber bug shouldn't take down the queue
    73→    }
    74→  });
    75→}
    76→
    77→function schedulePersist() {
    78→  if (persistTimer) return;
    79→  persistTimer = setTimeout(() => {
    80→    persistTimer = null;
    81→    AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(memMap)).catch(() => {});
    82→  }, 1000);
    83→}
    84→
    85→async function ensureCacheDir(): Promise<string | null> {
    86→  if (cacheDir) return cacheDir;
    87→  const root = FileSystem.cacheDirectory;
    88→  if (!root) return null;
    89→  cacheDir = root + CACHE_DIR_NAME;
    90→  try {
    91→    const info = await FileSystem.getInfoAsync(cacheDir);
    92→    if (!info.exists) {
    93→      await FileSystem.makeDirectoryAsync(cacheDir, { intermediates: true });
    94→    }
    95→  } catch {
    96→    // best-effort
    97→  }
    98→  return cacheDir;
    99→}
   100→
   101→async function init(): Promise<void> {
   102→  if (initPromise) return initPromise;
   103→  initPromise = (async () => {
   104→    await ensureCacheDir();
   105→    try {
   106→      const raw = await AsyncStorage.getItem(STORAGE_KEY);
   107→      if (raw) {
   108→        const parsed = JSON.parse(raw);
   109→        if (parsed && typeof parsed === 'object') {
   110→          memMap = parsed as Record<string, string>;
   111→        }
   112→      }
   113→    } catch {
   114→      // corrupt JSON — start fresh
   115→      memMap = {};
   116→    }
   117→  })();
   118→  return initPromise;
   119→}
   120→
   121→function get(id: string): string | null {
   122→  return memMap[id] || null;
   123→}
   124→
   125→function subscribe(id: string, cb: (p: string | null) => void): () => void {
   126→  let set = subs.get(id);
   127→  if (!set) {
   128→    set = new Set();
   129→    subs.set(id, set);
   130→  }
   131→  set.add(cb);
   132→  return () => {
   133→    const s = subs.get(id);
   134→    if (!s) return;
   135→    s.delete(cb);
   136→    if (s.size === 0) subs.delete(id);
   137→  };
   138→}
   139→
   140→async function generateOne(item: ThumbItem): Promise<void> {
   141→  // For an existing entry, double-check the file is still there. The OS can
   142→  // wipe the cache directory under storage pressure between sessions.
   143→  const existing = memMap[item.id];
   144→  if (existing) {
   145→    try {
   146→      const info = await FileSystem.getInfoAsync(existing);
   147→      if (info.exists && (info as any).size > 0) {
   148→        return; // still good — nothing to do
   149→      }
   150→    } catch {
   151→      // fall through and regenerate
   152→    }
   153→    delete memMap[item.id];
   154→  }
   155→
   156→  if (item.type === 'image') {
   157→    // For images we don't keep a separate file — expo-image's own disk
   158→    // cache is already a fast file-system lookup keyed by URI hash. We
   159→    // just warm it with a single prefetch call and from then on every
   160→    // grid render is a memory/disk hit, not a content:// round-trip.
   161→    if (imagesPrefetched.has(item.uri)) return;
   162→    imagesPrefetched.add(item.uri);
   163→    try {
   164→      await ExpoImage.prefetch(item.uri, 'memory-disk');
   165→    } catch {
   166→      // prefetch failure is harmless — Glide will still try on first paint
   167→    }
   168→    return;
   169→  }
   170→
   171→  // Videos: extract first key-frame as a JPG once and reuse forever.
   172→  //
   173→  // NATIVE PATH (EAS / custom build):
   174→  //   SafReaderModule.generateThumbnail runs Android's hardware-accelerated
   175→  //   MediaMetadataRetriever entirely in Java — no JS bridge overhead, no
   176→  //   second process hop. It writes atomically via .tmp+rename itself.
   177→  //   A 3 s timeout guards against the MediaMetadataRetriever hang seen on
   178→  //   MIUI / HyperOS and Samsung OneUI: setDataSource(context, uri) never
   179→  //   throws and never resolves for certain SAF content:// URIs, which
   180→  //   stalls the entire queue. On timeout we fall through to the JS path.
   181→  //
   182→  // JS FALLBACK (Expo Go / no native module / native timeout):
   183→  //   expo-video-thumbnails — also hardware-accelerated but crosses the
   184→  //   JS bridge twice (request + result) and writes to a temp dir that
   185→  //   we then have to move into our managed cache dir.
   186→  const dir = await ensureCacheDir();
   187→  if (!dir) return;
   188→  const dest = `${dir}vid_${safeFilename(item.id)}.jpg`;
   189→
   190→  // Helper: run expo-video-thumbnails and move result into managed dest.
   191→  async function jsThumb(): Promise<void> {
   192→    const tmp = `${dest}.tmp`;
   193→    const result = await VideoThumbnails.getThumbnailAsync(item.uri, {
   194→      time: 0,
   195→      quality: 0.5,
   196→    });
